/** The modifiers, in the order a chord writes them, and the flag each is. */
const MODIFIERS = [
  ["Control", "ctrlKey"],
  ["Alt", "altKey"],
  ["Shift", "shiftKey"],
  ["Super", "metaKey"],
];

/** The keys that are modifiers, by the `key` an engine gives them. */
