/** What `nc_schema::keys` prints for a key that is not a letter or a digit. */
const PRINTED = new Map([
  ["ArrowUp", "Up"],
  ["ArrowDown", "Down"],
  ["ArrowLeft", "Left"],
  ["ArrowRight", "Right"],
  ["Minus", "-"],
  ["Equal", "="],
  ["BracketLeft", "["],
  ["BracketRight", "]"],
  ["Backslash", "\\"],
  ["Semicolon", ";"],
  ["Quote", "'"],
  ["Backquote", "`"],
  ["Comma", ","],
  ["Period", "."],
  ["Slash", "/"],
]);

/** A Mac's own names for three keys. */
const MAC = new Map([
  ["Enter", "Return"],
  ["Backspace", "Delete"],
  ["Delete", "Forward Delete"],
]);

/** The keys that print a character, whose label a layout can change. */
const PRINTS = /^(Key[A-Z]|Digit[0-9]|Minus|Equal|BracketLeft|BracketRight|Backslash|Semicolon|Quote|Backquote|Comma|Period|Slash)$/;

/** The label each printing key has on the layout in use, once it is known. */
const layout = new Map();

/** Whether the engine said what the layout is, which outranks a typed key. */
