/** A key event as a chord, or `null` for a key that cannot end one. */
export function chordOf(event) {
  if (!event.code || MODIFIER_KEYS.has(event.key)) return null;
  return [...heldBy(event), event.code].join("+");
}

/** The modifiers an event says are held, in the order a chord writes them. */
